x-direction: column;\n  transition: margin-left .25s ease;\n}\n\n/* ── TOPBAR ──────────────────────────────────────────────── */\n#topbar {\n  position: sticky; top: 0;\n  height: var(--th);\n  background: #fff;\n  border-bottom: 1px solid var(--border);\n  z-index: 1040;\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 0 1.5rem;\n  box-shadow: var(--shadow);\n  flex-shrink: 0;\n}\n\n.tb-left { display: flex; align-items: center; gap: .75rem; }\n\n.btn-sb-tog {\n  background: none; border: none; cursor: pointer;\n  color: var(--muted); font-size: 1.3rem;\n  padding: .25rem .4rem; border-radius: 6px;\n  display: none;\n  transition: background .15s;\n}\n.btn-sb-tog:hover { background: var(--mint-bg); color: var(--maroon); }\n\n.tb-crumb { font-size: .8rem; color: var(--muted); }\n.tb-crumb .cur { color: var(--maroon); font-weight: 500; }\n\n.tb-right { display: flex; align-items: center; gap: .4rem; }\n\n.tb-ic {\n  background: none; border: none; cursor: pointer;\n  width: 36px; height: 36px; border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n  color: var(--muted); font-size: 1rem;\n  position: relative;\n  transition: background .15s;\n}\n.tb-ic:hover { background: var(--mint-bg); color: var(--maroon); }\n\n.notif-dot {\n  position: absolute; top: 5px; right: 5px;\n  width: 8px; height: 8px;\n  background: #ef4444; border-radius: 50%;\n  border: 2px solid #fff;\n}\n\n.tb-av {\n  width: 32px; height: 32px;\n  background: var(--maroon); color: #fff;\n  border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n  font-weight: 600; font-size: .85rem;\n}\n\n.tb-user {\n  display: flex; align-items: center; gap: .5rem;\n  background: none; border: 1px solid var(--border);\n  border-radius: 20px; padding: 3px 10px 3px 4px;\n  cursor: pointer; font-size: .82rem; color: var(--text);\n  transition: background .15s;\n}\n.tb-user:hover { background: var(--mint-bg); border-color: var(--mint); }\n\n.notif-drop { width: 320px; padding: 0; }\n.notif-drop .dropdown-header {\n  font-size: .75rem; font-weight: 600;\n  text-transform: uppercase; letter-spacing: .05em;\n  color: var(--muted); padding: .75rem 1rem;\n  border-bottom: 1px solid var(--border);\n}\n.notif-item {\n  display: flex; align-items: flex-start;\n  gap: .75rem; padding: .75rem 1rem;\n  border-bottom: 1px solid #f9f9f9;\n}\n.notif-item:hover { background: var(--mint-bg); }\n.notif-t  { font-size: .82rem; color: var(--text); }\n.notif-ts { font-size: .7rem; color: var(--muted); margin-top: 2px; }\n\n/* ── PAGE CONTENT ────────────────────────────────────────── */\n.page-content { flex: 1; padding: 1.5rem; }\n\n.page-hd { margin-bottom: 1.5rem; }\n.page-ttl { font-size: 1.2rem; font-weight: 600; color: var(--text); }\n.page-stl { font-size: .78rem; color: var(--muted); margin-top: 2px; }\n\n/* ── STAT CARDS ──────────────────────────────────────────── */\n.stat-card {\n  background: #fff;\n  border-radius: 10px;\n  padding: 1.1rem 1.25rem;\n  border-top: 3px solid var(--maroon);\n  box-shadow: var(--shadow);\n  display: flex; justify-content: space-between; align-items: flex-start;\n  height: 100%;\n}\n\n.sc-total    { border-top-color: var(--maroon); }\n.sc-masuk    { border-top-color: #64748b; }\n.sc-diproses { border-top-color: #f59e0b; }\n.sc-verif    { border-top-color: #3b82f6; }\n.sc-selesai  { border-top-color: #10b981; }\n.sc-ditolak  { border-top-color: #ef4444; }\n\n.sc-num { font-size: 2rem; font-weight: 700; line-height: 1; color: var(--text); }\n.sc-lbl { font-size: .68rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin-top: 5px; }\n.sc-ic  { font-size: 2rem; opacity: .1; line-height: 1; }\n\n/* ── CARD PANEL ──────────────────────────────────────────── */\n.card-panel {\n  background: #fff;\n  border-radius: 10px;\n  box-shadow: var(--shadow);\n  border: 1px solid var(--border);\n  overflow: hidden;\n  height: 100%;\n}\n\n.cp-head {\n  padding: .9rem 1.25rem;\n  border-bottom: 1px solid var(--border);\n  display: flex; align-items: center; justify-content: space-between;\n}\n\n.cp-title { font-size: .88rem; font-weight: 600; color: var(--text); }\n.cp-sub   { font-size: .72rem; color: var(--muted); margin-top: 2px; }\n.cp-body  { padding: 1.25rem; }\n.chart-wrap { position: relative; height: 250px; }\n\n/* ── TABLE ───────────────────────────────────────────────── */\n.sipplh-table { margin: 0; font-size: .82rem; }\n\n.sipplh-table thead th {\n  background: #f9fafb;\n  font-size: .68rem; text-transform: uppercase;\n  letter-spacing: .06em; color: var(--muted);\n  font-weight: 600; border-bottom: 2px solid var(--border);\n  padding: .7rem 1rem; white-space: nowrap;\n  border-top: none;\n}\n\n.sipplh-table tbody td {\n  padding: .7rem 1rem;\n  vertical-align: middle;\n  border-bottom: 1px solid #f3f4f6;\n  color: var(--text);\n}\n.sipplh-table tbody tr:last-child td { border-bottom: none; }\n.sipplh-table tbody tr:hover td { background: #fafdf9; }\n\n/* ── BADGES ──────────────────────────────────────────────── */\n.badge { font-weight: 500; font-size: .72rem; }\n.badge-kat {\n  background: rgba(106,0,0,.08); color: var(--maroon);\n  font-size: .69rem; padding: 2px 7px;\n  border-radius: 4px; font-weight: 500;\n}\n\n/* ── BUTTONS ─────────────────────────────────────────────── */\n.btn-maroon { background: var(--maroon); color: #fff; border: none; }\n.btn-maroon:hover { background: var(--maroon-dk); color: #fff; }\n.btn-outline-maroon { color: var(--maroon); border-color: var(--maroon); }\n.btn-outline-maroon:hover { background: var(--maroon); color: #fff; }\n.btn-xs { padding: .2rem .6rem; font-size: .72rem; border-radius: 4px; }\n\n/* ── LOGIN ───────────────────────────────────────────────── */\n.login-wrap { min-height: 100vh; display: flex; }\n\n.login-left {\n  width: 420px; flex-shrink: 0;\n  background: var(--maroon);\n  padding: 3rem 2.5rem;\n  display: flex; flex-direction: column;\n  justify-