"sc-lbl">Selesai</div>\n      </div>\n      <i class="bi bi-check-circle-fill sc-ic text-success"></i>\n    </div>\n  </div>\n\n  <div class="col-6 col-md-4 col-xl-2">\n    <div class="stat-card sc-ditolak">\n      <div>\n        <div class="sc-num">{{ $stats[\'ditolak\'] }}</div>\n        <div class="sc-lbl">Ditolak</div>\n      </div>\n      <i class="bi bi-x-circle-fill sc-ic text-danger"></i>\n    </div>\n  </div>\n\n</div>\n\n{{-- CHARTS ROW --}}\n<div class="row g-3 mb-4">\n\n  {{-- Line Chart: Tren Bulanan --}}\n  <div class="col-12 col-xl-8">\n    <div class="card-panel">\n      <div class="cp-head">\n        <div>\n          <div class="cp-title">Tren Pengaduan {{ now()->year }}</div>\n          <div class="cp-sub">Jumlah pengaduan per bulan sepanjang tahun berjalan</div>\n        </div>\n      </div>\n      <div class="cp-body">\n        <div class="chart-wrap"><canvas id="trendChart"></canvas></div>\n      </div>\n    </div>\n  </div>\n\n  {{-- Doughnut: Status Breakdown --}}\n  <div class="col-12 col-xl-4">\n    <div class="card-panel">\n      <div class="cp-head">\n        <div class="cp-title">Status Pengaduan</div>\n      </div>\n      <div class="cp-body">\n        <div class="chart-wrap"><canvas id="statusChart"></canvas></div>\n      </div>\n    </div>\n  </div>\n\n</div>\n\n{{-- RECENT PENGADUAN TABLE --}}\n<div class="card-panel">\n  <div class="cp-head">\n    <div>\n      <div class="cp-title">Pengaduan Terbaru</div>\n      <div class="cp-sub">5 pengaduan yang terakhir masuk</div>\n    </div>\n    <a href="{{ route(\'admin.pengaduan.index\') }}" class="btn btn-sm btn-outline-maroon">\n      Lihat Semua <i class="bi bi-arrow-right ms-1"></i>\n    </a>\n  </div>\n\n  <div class="table-responsive">\n    <table class="table sipplh-table">\n      <thead>\n        <tr>\n          <th>No. Pengaduan</th>\n          <th>Tanggal</th>\n          <th>Pelapor</th>\n          <th>Kategori</th>\n          <th>Lokasi</th>\n          <th>Status</th>\n          <th>Aksi</th>\n        </tr>\n      </thead>\n      <tbody>\n        @forelse($recentPengaduan as $p)\n        <tr>\n          <td><code>{{ $p->nomor_pengaduan }}</code></td>\n          <td>{{ $p->tanggal_pengaduan->format(\'d M Y\') }}</td>\n          <td>{{ $p->pelapor?->anonim ? \'Anonim\' : ($p->pelapor?->nama_pelapor ?? \'—\') }}</td>\n          <td><span class="badge-kat">{{ str_replace(\'_\', \' \', $p->kategori) }}</span></td>\n          <td>{{ $p->kecamatan?->nama_kecamatan ?? \'—\' }}</td>\n          <td>\n            @php $badge = match($p->status) {\n              \'masuk\'      => \'secondary\',\n              \'diproses\'   => \'warning\',\n              \'verifikasi\' => \'primary\',\n              \'selesai\'    => \'success\',\n              \'ditolak\'    => \'danger\',\n              default      => \'secondary\'\n            }; @endphp\n            <span class="badge bg-{{ $badge }}">{{ ucfirst($p->status) }}</span>\n          </td>\n          <td>\n            <a href="{{ route(\'admin.pengaduan.show\', $p) }}" class="btn btn-xs btn-outline-secondary">\n              <i class="bi bi-eye"></i>\n            </a>\n          </td>\n        </tr>\n        @empty\n        <tr>\n          <td colspan="7">\n            <div class="empty-state">\n              <i class="bi bi-inbox"></i>\n              Belum ada data pengaduan. <a href="{{ route(\'admin.pengaduan.create\') }}">Tambah pengaduan pertama</a>\n            </div>\n          </td>\n        </tr>\n        @endforelse\n      </tbody>\n    </table>\n  </div>\n</div>\n\n@endsection\n\n@push(\'scripts\')\n<script>\nconst months = [\'Jan\',\'Feb\',\'Mar\',\'Apr\',\'Mei\',\'Jun\',\'Jul\',\'Agu\',\'Sep\',\'Okt\',\'Nov\',\'Des\'];\nconst chartData = @json($chartData);\nconst stats = {\n  masuk:      {{ $stats[\'masuk\'] }},\n  diproses:   {{ $stats[\'diproses\'] }},\n  verifikasi: {{ $stats[\'verifikasi\'] }},\n  selesai:    {{ $stats[\'selesai\'] }},\n  ditolak:    {{ $stats[\'ditolak\'] }},\n};\n\n// ── Trend Line Chart ─────────────────────────────\nnew Chart(document.getElementById(\'trendChart\'), {\n  type: \'line\',\n  data: {\n    labels: months,\n    datasets: [{\n      label: \'Pengaduan\',\n      data: chartData,\n      borderColor: \'#6A0000\',\n      backgroundColor: \'rgba(106,0,0,.07)\',\n      borderWidth: 2,\n      fill: true,\n      tension: 0.4,\n      pointBackgroundColor: \'#6A0000\',\n      pointBorderColor: \'#fff\',\n      pointBorderWidth: 2,\n      pointRadius: 5,\n      pointHoverRadius: 7,\n    }]\n  },\n  options: {\n    responsive: true, maintainAspectRatio: false,\n    plugins: {\n      legend: { display: false },\n      tooltip: {\n        callbacks: {\n          title: (i) => \'Bulan \' + i[0].label,\n          label: (i) => \' \' + i.parsed.y + \' pengaduan\',\n        }\n      }\n    },\n    scales: {\n      y: {\n        beginAtZero: true,\n        ticks: { stepSize: 1, font: { size: 11 } },\n        grid: { color: \'rgba(0,0,0,.04)\' }\n      },\n      x: {\n        ticks: { font: { size: 11 } },\n        grid: { display: false }\n      }\n    }\n  }\n});\n\n// ── Status Doughnut Chart ────────────────────────\nnew Chart(document.getElementById(\'statusChart\'), {\n  type: \'doughnut\',\n  data: {\n    labels: [\'Masuk\',\'Diproses\',\'Verifikasi\',\'Selesai\',\'Ditolak\'],\n    datasets: [{\n      data: [stats.masuk, stats.diproses, stats.verifikasi, stats.selesai, stats.ditolak],\n      backgroundColor: [\'#94a3b8\',\'#f59e0b\',\'#3b82f6\',\'#10b981\',\'#ef4444\'],\n      borderWidth: 0,\n      hoverOffset: 8,\n    }]\n  },\n  options: {\n    responsive: true, maintainAspectRatio: false,\n    cutout: \'65%\',\n    plugins: {\n      legend: {\n        position: \'bottom\',\n        labels: { padding: 14, font: { size: 11 }, usePointStyle: true }\n      }\n    }\n  }\n});\n</script>\n@endpush\n')
