# DashboardController.php
os.makedirs(os.path.dirname('src/app/Http/Controllers/Admin/DashboardController.php'), exist_ok=True)
with open('src/app/Http/Controllers/Admin/DashboardController.php', 'w') as _f:
    _f.write('<?php\nnamespace App\\Http\\Controllers\\Admin;\n\nuse App\\Http\\Controllers\\Controller;\nuse App\\Models\\Pengaduan;\nuse App\\Models\\User;\n\nclass DashboardController extends Controller\n{\n    public function index()\n    {\n        $stats = [\n            \'total\'      => Pengaduan::count(),\n            \'masuk\'      => Pengaduan::where(\'status\', \'masuk\')->count(),\n            \'diproses\'   => Pengaduan::where(\'status\', \'diproses\')->count(),\n            \'verifikasi\' => Pengaduan::where(\'status\', \'verifikasi\')->count(),\n            \'selesai\'    => Pengaduan::where(\'status\', \'selesai\')->count(),\n            \'ditolak\'    => Pengaduan::where(\'status\', \'ditolak\')->count(),\n        ];\n\n        // Chart: pengaduan per bulan tahun berjalan\n        $monthly = Pengaduan::selectRaw(\'MONTH(tanggal_pengaduan) as bulan, COUNT(*) as total\')\n            ->whereYear(\'tanggal_pengaduan\', now()->year)\n            ->groupBy(\'bulan\')\n            ->pluck(\'total\', \'bulan\')\n            ->toArray();\n\n        $chartData = [];\n        for ($i = 1; $i <= 12; $i++) {\n            $chartData[] = $monthly[$i] ?? 0;\n        }\n\n        $recentPengaduan = Pengaduan::with([\'pelapor\', \'kecamatan\'])\n            ->latest()\n            ->take(5)\n            ->get();\n\n        return view(\'admin.dashboard.index\', compact(\'stats\', \'chartData\', \'recentPengaduan\'));\n    }\n}\n')
print("  ✅  src/app/Http/Controllers/Admin/DashboardController.php")

